import type { Point } from "@stallion/geometry";

export type PointerKind = "mouse" | "pen" | "touch";

export type PointerDown = {
  pointerId: number;
  kind: PointerKind;
  button: number;
  point: Point;
  time: number;
};

export type Modifiers = { panTool: boolean; spaceDown: boolean };

export type Effect =
  | { type: "StartStroke"; secondary: boolean; point: Point }
  | { type: "ExtendStroke" }
  | { type: "CommitStroke" }
  | { type: "DiscardStroke" }
  | { type: "Pan"; dx: number; dy: number }
  | { type: "Pinch"; from: readonly [Point, Point]; to: readonly [Point, Point] };

type Tracked = { point: Point; kind: PointerKind };

type State =
  | { mode: "Idle" }
  | { mode: "Pending"; pointerId: number; point: Point; time: number }
  | { mode: "Draw"; pointerId: number }
  | { mode: "Pan"; pointerId: number }
  | { mode: "Pinch" };

export type Gestures = {
  down(event: PointerDown, modifiers: Modifiers): Effect[];
  move(pointerId: number, point: Point, time: number): Effect[];
  tick(time: number): Effect[];
  up(pointerId: number): Effect[];
  cancel(pointerId: number): Effect[];
};

const PRIMARY = 0;
const MIDDLE = 1;
const SECONDARY = 2;

export const PENDING_MS = 60;
const PENDING_SLOP_PX = 6;

export function createGestures(): Gestures {
  const pointers = new Map<number, Tracked>();
  let state: State = { mode: "Idle" };
  let penSeen = false;

  const touchIds = (): number[] =>
    [...pointers.entries()].filter(([, tracked]) => tracked.kind === "touch").map(([id]) => id);

  const wantsPan = (event: PointerDown, modifiers: Modifiers): boolean => {
    if (event.button === MIDDLE) return true;
    if (event.button !== PRIMARY) return false;
    if (modifiers.panTool || modifiers.spaceDown) return true;
    return event.kind === "touch" && penSeen;
  };

  const down = (event: PointerDown, modifiers: Modifiers): Effect[] => {
    pointers.set(event.pointerId, { point: event.point, kind: event.kind });
    if (event.kind === "pen") penSeen = true;

    if (event.kind === "touch" && touchIds().length >= 2) {
      if (state.mode === "Pending") {
        state = { mode: "Pinch" };
        return [];
      }
      const discard = state.mode === "Draw" && pointers.get(state.pointerId)?.kind === "touch";
      if (state.mode === "Draw" && !discard) return [];
      state = { mode: "Pinch" };
      return discard ? [{ type: "DiscardStroke" }] : [];
    }

    if (state.mode !== "Idle") return [];
    if (wantsPan(event, modifiers)) {
      state = { mode: "Pan", pointerId: event.pointerId };
      return [];
    }
    if (event.button !== PRIMARY && event.button !== SECONDARY) return [];
    if (event.kind === "touch") {
      state = { mode: "Pending", pointerId: event.pointerId, point: event.point, time: event.time };
      return [];
    }
    state = { mode: "Draw", pointerId: event.pointerId };
    return [{ type: "StartStroke", secondary: event.button === SECONDARY, point: event.point }];
  };

  const promote = (): Effect[] => {
    if (state.mode !== "Pending") return [];
    const { pointerId, point } = state;
    state = { mode: "Draw", pointerId };
    return [{ type: "StartStroke", secondary: false, point }];
  };

  const tick = (time: number): Effect[] =>
    state.mode === "Pending" && time - state.time >= PENDING_MS ? promote() : [];

  const pinchEffect = (pointerId: number, point: Point): Effect[] => {
    const [first, second] = touchIds();
    if (first === undefined) return [];
    if (second === undefined) {
      const previous = pointers.get(first)?.point;
      if (first !== pointerId || !previous) return [];
      return [{ type: "Pan", dx: point.x - previous.x, dy: point.y - previous.y }];
    }
    if (pointerId !== first && pointerId !== second) return [];
    const a = pointers.get(first)?.point;
    const b = pointers.get(second)?.point;
    if (!a || !b) return [];
    const from = [a, b] as const;
    const to = pointerId === first ? ([point, b] as const) : ([a, point] as const);
    return [{ type: "Pinch", from, to }];
  };

  const move = (pointerId: number, point: Point, time: number): Effect[] => {
    const tracked = pointers.get(pointerId);
    if (!tracked) return [];
    const effects: Effect[] = [];
    if (state.mode === "Pending" && state.pointerId === pointerId) {
      const travelled = Math.hypot(point.x - state.point.x, point.y - state.point.y);
      if (travelled <= PENDING_SLOP_PX && time - state.time < PENDING_MS) {
        pointers.set(pointerId, { ...tracked, point });
        return [];
      }
      effects.push(...promote());
    }
    if (state.mode === "Draw" && state.pointerId === pointerId) {
      effects.push({ type: "ExtendStroke" });
    }
    if (state.mode === "Pan" && state.pointerId === pointerId) {
      effects.push({ type: "Pan", dx: point.x - tracked.point.x, dy: point.y - tracked.point.y });
    }
    if (state.mode === "Pinch") effects.push(...pinchEffect(pointerId, point));
    pointers.set(pointerId, { ...tracked, point });
    return effects;
  };

  const end = (pointerId: number, cancelled: boolean): Effect[] => {
    if (!pointers.delete(pointerId)) return [];
    const effects: Effect[] = [];
    if (state.mode === "Pending" && state.pointerId === pointerId) {
      if (!cancelled) effects.push(...promote());
      else state = { mode: "Idle" };
    }
    if (state.mode === "Draw" && state.pointerId === pointerId) {
      effects.push({ type: cancelled ? "DiscardStroke" : "CommitStroke" });
      state = touchIds().length > 0 ? { mode: "Pinch" } : { mode: "Idle" };
    }
    if (state.mode === "Pan" && state.pointerId === pointerId) state = { mode: "Idle" };
    if (state.mode === "Pinch" && touchIds().length === 0) state = { mode: "Idle" };
    if (pointers.size === 0) state = { mode: "Idle" };
    return effects;
  };

  return {
    down,
    move,
    tick,
    up: (pointerId) => end(pointerId, false),
    cancel: (pointerId) => end(pointerId, true),
  };
}
import { expect, test } from "vitest";
import { createGestures, type Effect, type PointerDown } from "./gesture";

const idle = { panTool: false, spaceDown: false };

const touch = (pointerId: number, x: number, y: number, time: number): PointerDown => ({
  pointerId,
  kind: "touch",
  button: 0,
  point: { x, y },
  time,
});

test("a second finger after the pending window turns a stroke into a pinch and discards it", () => {
  const gestures = createGestures();
  const effects: Effect[] = [
    ...gestures.down(touch(1, 100, 100, 0), idle),
    ...gestures.move(1, { x: 102, y: 100 }, 100),
    ...gestures.down(touch(2, 200, 100, 120), idle),
    ...gestures.move(1, { x: 60, y: 140 }, 130),
    ...gestures.move(2, { x: 260, y: 140 }, 140),
    ...gestures.up(1),
    ...gestures.up(2),
  ];
  const types = effects.map((effect) => effect.type);
  expect(types).toEqual(["StartStroke", "ExtendStroke", "DiscardStroke", "Pinch", "Pinch"]);
  expect(effects.at(-1)).toEqual({
    type: "Pinch",
    from: [
      { x: 60, y: 140 },
      { x: 200, y: 100 },
    ],
    to: [
      { x: 60, y: 140 },
      { x: 260, y: 140 },
    ],
  });
});

test("two touches 30 ms apart pan the board and never start an erase, while a tap still erases", () => {
  const gestures = createGestures();
  const pan: Effect[] = [
    ...gestures.down(touch(1, 100, 100, 0), idle),
    ...gestures.down(touch(2, 200, 100, 30), idle),
    ...gestures.tick(90),
    ...gestures.move(1, { x: 140, y: 100 }, 100),
    ...gestures.move(2, { x: 240, y: 100 }, 100),
    ...gestures.up(1),
    ...gestures.up(2),
  ];
  const types = pan.map((effect) => effect.type);
  expect(types).toEqual(["Pinch", "Pinch"]);
  expect(types.filter((type) => type === "StartStroke" || type === "ExtendStroke")).toEqual([]);

  const tap: Effect[] = [...gestures.down(touch(3, 100, 100, 500), idle), ...gestures.up(3)];
  expect(tap).toEqual([
    { type: "StartStroke", secondary: false, point: { x: 100, y: 100 } },
    { type: "CommitStroke" },
  ]);
});

test("a single touch starts once it moves past the slop or holds past the window", () => {
  const moved = createGestures();
  expect(moved.down(touch(1, 0, 0, 0), idle)).toEqual([]);
  expect(moved.move(1, { x: 3, y: 0 }, 10)).toEqual([]);
  expect(moved.move(1, { x: 20, y: 0 }, 20).map((effect) => effect.type)).toEqual([
    "StartStroke",
    "ExtendStroke",
  ]);

  const held = createGestures();
  held.down(touch(1, 0, 0, 0), idle);
  expect(held.tick(30)).toEqual([]);
  expect(held.tick(60)).toEqual([{ type: "StartStroke", secondary: false, point: { x: 0, y: 0 } }]);
});

test("mouse and pen start a stroke on pointerdown", () => {
  const gestures = createGestures();
  const down = { pointerId: 1, kind: "pen", button: 0, point: { x: 5, y: 5 }, time: 0 } as const;
  expect(gestures.down(down, idle)).toEqual([
    { type: "StartStroke", secondary: false, point: { x: 5, y: 5 } },
  ]);
});
import type { BBox, Point } from "@stallion/geometry";
import { MAX_LEVEL, MIN_LEVEL } from "@stallion/geometry";

export type Camera = { x: number; y: number; zoom: number };

export const MIN_ZOOM = 2 ** -MAX_LEVEL;
export const MAX_ZOOM = 2 ** -MIN_LEVEL;

export const clampZoom = (zoom: number): number => Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, zoom));

export const screenToWorld = (camera: Camera, screen: Point): Point => ({
  x: camera.x + screen.x / camera.zoom,
  y: camera.y + screen.y / camera.zoom,
});

export const worldToScreen = (camera: Camera, world: Point): Point => ({
  x: (world.x - camera.x) * camera.zoom,
  y: (world.y - camera.y) * camera.zoom,
});

export const viewBounds = (camera: Camera, width: number, height: number): BBox => ({
  minX: camera.x,
  minY: camera.y,
  maxX: camera.x + width / camera.zoom,
  maxY: camera.y + height / camera.zoom,
});

export const pan = (camera: Camera, dx: number, dy: number): Camera => ({
  x: camera.x - dx / camera.zoom,
  y: camera.y - dy / camera.zoom,
  zoom: camera.zoom,
});

export const zoomAt = (camera: Camera, screen: Point, factor: number): Camera => {
  const anchor = screenToWorld(camera, screen);
  const zoom = clampZoom(camera.zoom * factor);
  return { x: anchor.x - screen.x / zoom, y: anchor.y - screen.y / zoom, zoom };
};

const midpoint = (a: Point, b: Point): Point => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });

const distance = (a: Point, b: Point): number => Math.hypot(a.x - b.x, a.y - b.y);

export const pinch = (
  camera: Camera,
  from: readonly [Point, Point],
  to: readonly [Point, Point],
): Camera => {
  const start = midpoint(...from);
  const end = midpoint(...to);
  const spread = distance(...from);
  const next = distance(...to);
  const factor = spread > 0 && next > 0 ? next / spread : 1;
  return pan(zoomAt(camera, start, factor), end.x - start.x, end.y - start.y);
};

export const wheelFactor = (deltaY: number, deltaMode: number): number => {
  const pixels = deltaMode === 1 ? deltaY * 16 : deltaMode === 2 ? deltaY * 800 : deltaY;
  return 2 ** (-pixels / 300);
};

