html,
body,
#app {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
  background: var(--paper);
  color: var(--ink);
  font-family: system-ui, sans-serif;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: none;
}

.board {
  position: fixed;
  inset: 0;
}

.surface {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: crosshair;
}

.surface.panning {
  cursor: grab;
}

.surface.selecting {
  cursor: default;
}

.surface.erasing {
  cursor: cell;
}

.toolbar {
  position: fixed;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 6px 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--panel);
  box-shadow: 0 2px 8px #0000001a;
}

.group {
  margin: 0;
  padding: 0;
  border: 0;
  min-width: 0;
  display: flex;
  gap: 4px;
}

.tool {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 8px;
  background: transparent;
  cursor: pointer;
}

.tool:focus {
  outline: none;
}

.tool:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.tool[aria-pressed="true"] {
  border-color: var(--accent);
}

.tool:disabled {
  opacity: 0.35;
  cursor: default;
}

.dot {
  display: block;
  border-radius: 50%;
  background: var(--ink);
}

.swatch {
  position: relative;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  box-shadow: inset 0 0 0 2px var(--panel);
}

.swatch[aria-pressed="true"] {
  border-color: transparent;
  box-shadow:
    inset 0 0 0 2px var(--panel),
    0 0 0 2px var(--panel),
    0 0 0 5px var(--ink);
}

.swatch.secondary::after {
  content: "";
  position: absolute;
  right: -5px;
  bottom: -5px;
  width: 10px;
  height: 10px;
  border: 2px solid var(--panel);
  border-radius: 50%;
  background: var(--ink);
}

.pair {
  position: relative;
}

.chip {
  position: absolute;
  width: 16px;
  height: 16px;
  border: 2px solid var(--panel);
  border-radius: 4px;
}

.chip.back {
  right: 4px;
  bottom: 4px;
}

.chip.front {
  left: 4px;
  top: 4px;
}

.error {
  position: fixed;
  left: 16px;
  right: 16px;
  bottom: 16px;
  padding: 12px 16px;
  border: 1px solid #e5484d;
  border-radius: 10px;
  background: #fff5f5;
  color: #8a1c1f;
  user-select: text;
  -webkit-user-select: text;
}

.error p {
  margin: 0 0 8px;
}

.status {
  width: 10px;
  height: 10px;
  margin: 0 4px;
  border-radius: 50%;
  background: #8b8d98;
}

.status[data-connection="Connected"] {
  background: #30a46c;
}

.status[data-connection="Reconnecting"] {
  background: #f76b15;
}

.status[data-connection="Offline"] {
  background: #e5484d;
}
