import { execFileSync } from "node:child_process";
const sha = process.argv[2];
const sleep = (ms) => Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
const deadline = Date.now() + 15 * 60 * 1000;
while (Date.now() < deadline) {
  let runs = [];
  try {
    runs = JSON.parse(execFileSync("gh", ["run", "list", "--repo", "mvhenten/stallion", "--workflow", "deploy.yml", "--limit", "1", "--json", "status,conclusion,headSha"], { encoding: "utf8" }));
  } catch (error) {
    console.log(`gh failed: ${String(error.message).split("\n")[0]}`);
  }
  const [run] = runs;
  console.log(new Date().toISOString(), JSON.stringify(run));
  if (run && run.headSha === sha && run.status === "completed") {
    console.log(`DONE ${run.conclusion}`);
    process.exit(run.conclusion === "success" ? 0 : 1);
  }
  sleep(30000);
}
console.log("TIMEOUT");
process.exit(2);
