const BASE = "https://stallion.matthijs-f49.workers.dev/b/";
mkdirSync(DIR, { recursive: true });

const results = [];
let errorCount = 0;
const expect = (cond, msg) => {
  if (!cond) throw new Error(msg);
};

const run = async (browser, scheme) => {
  const board = `gest-${scheme}-${Date.now()}`;
  const context = await browser.newContext({ ...devices["Galaxy Tab S9"], colorScheme: scheme });
  const page = await context.newPage();
  const errors = [];
  page.on("console", (m) => {
    if (m.type() !== "error") return;
    if (/favicon/.test(m.location().url) || /favicon/.test(m.text())) return;
    errors.push(m.text());
  });
  page.on("pageerror", (e) => errors.push(e.message));
  await page.goto(BASE + board, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible" });
  await page.waitForTimeout(800);
  const cdp = await context.newCDPSession(page);
  const send = (type, pts) =>
    cdp.send("Input.dispatchTouchEvent", {
      type,
      touchPoints: pts.map((p, i) => ({ x: p.x, y: p.y, id: i + 1, radiusX: 2, radiusY: 2 })),
    });
  const camera = () =>
    page.evaluate((b) => JSON.parse(localStorage.getItem(`stallion:camera:${b}`) ?? "null"), board);
  const chip = page.locator(".level-chip");
  const shot = (name) => page.screenshot({ path: join(DIR, `${scheme}-${name}.png`) });
  const vp = page.viewportSize();
  const cx = vp.width / 2;
  const cy = vp.height / 2;

  await send("touchStart", [{ x: cx - 150, y: cy }]);
  for (let i = 1; i <= 20; i++) await send("touchMove", [{ x: cx - 150 + i * 15, y: cy + Math.sin(i / 3) * 40 }]);
  await send("touchEnd", []);
  await page.waitForTimeout(500);
  await shot("1-draw");
  const drawn = (await camera()) ?? { x: 0, y: 0, zoom: 1 };
  const level0 = (await chip.innerText()).trim();

  const a = { x: cx - 100, y: cy + 100 };
  const b = { x: cx + 100, y: cy + 100 };
  await send("touchStart", [a]);
  await send("touchStart", [a, b]);
  for (let i = 1; i <= 15; i++) {
    await send("touchMove", [
      { x: a.x + i * 8, y: a.y - i * 6 },
      { x: b.x + i * 8, y: b.y - i * 6 },
    ]);
  }
  await send("touchEnd", [{ x: b.x + 120, y: b.y - 90 }]);
  await send("touchEnd", []);
  await page.waitForTimeout(500);
  await shot("2-two-finger-pan");
